window.RP_SESSION={"id":"S-d4599758e7d0","messages":[{"id":"RP-0152668","time":"2026-05-07T17:31:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"검을 휘두른다.\n\n허나 휘둘리는것은 몸으로 검을 쥐는것이 아니라 검에 쥐어 휘둘리는것처럼 마치 부나방처럼 앞의 적을 향해 춤추듯이 나아간다.\n\n또 허나 바람처럼 흐르듯 한끝차이로 몸을 비틀고 물흐르듯 나아간다.\n\n스승님께 배운것처럼.","characters":["P-adf3e19364b5"]},{"id":"RP-0152669","time":"2026-05-07T17:31:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-adf3e19364b5"]},{"id":"RP-0152670","time":"2026-05-07T17:31:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'랜슬롯'의 민첩 판정 :\n[9] + [2] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0152671","time":"2026-05-07T17:33:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"완벽한 연무, 길드에 들어와 몇몇임무를 하며 본인의 약함에 착잡해진 마음을 녹여주듯 그녀는 검을 내리고 주저앉아 하늘을 쳐다본다.","characters":["P-adf3e19364b5"]},{"id":"RP-0152672","time":"2026-05-07T17:37:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"\" 역시 나야... \"\n\n하지만\n\n\" 이걸로는 안되는 걸까. \"\n\n정령을 불러봅니다.","characters":["P-adf3e19364b5"]},{"id":"RP-0152673","time":"2026-05-07T17:37:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-adf3e19364b5"]},{"id":"RP-0152674","time":"2026-05-07T17:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'랜슬롯'의 매력 판정 :\n[3] + [1] = [4]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0152675","time":"2026-05-07T17:41:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"\" 후우..됐어.. \"\n\n한숨을 쉬고선 다시 검을 쥐고 일어섭니다.\n\n한바퀴 두바퀴 빠른 연격, 그리고 찌르기.\n\n\" 나는 호수의 랜슬롯. 언젠가는...최강이 될거니까.. \"\n\n검을 땅에 꽂고 울으며 맹세합니다. 처음 검을 쥐었던 그날처럼.\n메시지가 삭제되었습니다.","characters":["P-adf3e19364b5"]},{"id":"RP-0152676","time":"2026-05-07T17:42:00+09:00","room":"RP","name":"랜슬롯","profile":"헥터","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-adf3e19364b5"]},{"id":"RP-0152677","time":"2026-05-07T17:42:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-0152678","time":"2026-05-07T22:20:00+09:00","room":"RP","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"!힘","characters":[]},{"id":"RP-0152679","time":"2026-05-07T22:20:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'하일로 조바'의 힘 판정 :\n[7] + [-1] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]}]};
